(async () => {
 const { mountPlus } = await import('/plus/plus.js'); const p = mountPlus(); await p.ready;
 const canvas = document.getElementById('screen'); const before = canvas.toDataURL();
 const input = await import('/engine/input.js'); const suspended = input.gamepad.suspended;
 const press = key => window.dispatchEvent(new KeyboardEvent('keydown', {key, bubbles:true,cancelable:true}));
 press('F12'); if (!p.isOpen || !input.gamepad.suspended) throw Error('panel did not suspend pad');
 for (const b of document.querySelectorAll('#por-plus [role=tab]')) { b.click(); if (b.getAttribute('aria-selected') !== 'true') throw Error('tab selection'); }
 p.selectTab('helpers'); const crisp = document.querySelector('[data-setting=crispFont]'); crisp.click();
 await new Promise(r => setTimeout(r,100));
 const {createStore} = await import('/plus/store.js'); const saved = await createStore().get('settings');
 if (!saved.crispFont) throw Error('setting did not persist');
 await p.setSetting('original', true); if (p.enabled('crispFont') || !document.getElementById('por-plus-menu').hidden) throw Error('master switch');
 press('Escape'); if (p.isOpen || input.gamepad.suspended !== suspended) throw Error('close failed');
 if (before !== canvas.toDataURL()) throw Error('canvas changed');
 press('F12'); if (!p.isOpen) throw Error('original mode cannot reopen');
 await p.setSetting('original', false); if (!p.enabled('crispFont')) throw Error('helper choice lost');
 press('Escape'); if (before !== canvas.toDataURL()) throw Error('canvas changed after restore');
 return {pass:true,tabs:document.querySelectorAll('#por-plus [role=tab]').length, canvasUnchanged:true, settingsPersisted:true};
})()
